text:
{
  "title_novice": "Объём массивной залежи — в её своде",
  "summary": [
    {"text": "Большинство рифовых залежей массивного типа: сверху их ограничивает выпуклая ловушка, снизу — плоский водонефтяной (ВНК) или газоводяной (ГВК) контакт.", "claims": ["c2", "c3", "c4"]},
    {"text": "Мощность такой залежи максимальна в центре и падает до нуля на крыльях, поэтому основной объём лежит в своде.", "claims": ["c5", "c6"]},
    {"text": "Значит, сетка скважин, равномерная по площади, охватывает объём залежи неравномерно.", "claims": ["c7"]}
  ],
  "claims": [
    {"key": "c1", "text": "Методика изучения подсчётных параметров и подготовки месторождения должна учитывать форму залежи.", "kind": "inference", "unit_id": "u-221-6be56e", "page": 221, "quote": "Методика проведения работ по изучению подсчетных параметров и подготовке месторождения к разработке должна учитывать то, что", "numbers": [], "question": null},
    {"key": "c2", "text": "Абсолютное большинство залежей нефти и газа, связанных с рифами, относится к массивному типу.", "kind": "observation", "unit_id": "u-221-6be56e", "page": 221, "quote": "абсолютное большинство связанных с рифами залежей нефти и газа", "numbers": [], "question": null},
    {"key": "c3", "text": "Массивный тип: залежь ограничена сверху выпуклой поверхностью ловушки.", "kind": "inference", "unit_id": "u-221-6be56e", "page": 222, "quote": "к массивному типу, т.е. ограничено сверху выпуклой поверхностью ловушки", "numbers": [], "question": null},
    {"key": "c4", "text": "Снизу массивная залежь ограничена плоскостью водонефтяного или газоводяного контакта. Это допущение модели.", "kind": "assumption", "unit_id": "u-221-6be56e", "page": 222, "quote": "а снизу плоскостью ВНК или ГВК", "numbers": [], "question": null},
    {"key": "c5", "text": "Из-за такой формы мощность залежи постепенно убывает от максимума в центре до нуля на крыльях.", "kind": "inference", "unit_id": "u-221-6be56e", "page": 222, "quote": "В связи с такой формой мощность залежи закономерно и более менее равномерно убывает от максимальной в центре до нулевой на крыльях", "numbers": [], "question": null},
    {"key": "c6", "text": "Объём залежи распределён по площади так же неравномерно: основная его доля в своде, меньшая — в приконтурной зоне.", "kind": "inference", "unit_id": "u-221-6be56e", "page": 222, "quote": "основная его доля сосредоточена в сводовой части, а на значительную по площади приконтурную зону приходится существенно меньшая часть", "numbers": [], "question": null},
    {"key": "c7", "text": "Если расставить скважины равномерно по площади или по профилям, объём залежи освещается неравномерно.", "kind": "inference", "unit_id": "u-221-6be56e", "page": 222, "quote": "Применение в этом случае равномерной по площади или по профилям сетки скважин приведет к неравномерному освещению объема залежи", "numbers": [], "question": null}
  ],
  "mechanism": [
    {"text": "Массивная залежь заполняет пространство между выпуклой поверхностью ловушки и плоским контактом.", "claims": ["c3", "c4"], "hypothesis": false},
    {"text": "Мощность залежи — это расстояние от поверхности ловушки до контакта. Она максимальна в центре и уменьшается к краям.", "claims": ["c5"], "hypothesis": false},
    {"text": "Объём — это мощность, распределённая по площади. Поэтому большая часть объёма лежит под сводом, где мощность велика.", "claims": ["c6"], "hypothesis": true}
  ],
  "practice": [
    {"text": "Сначала проверь тип залежи: сверху должна быть выпуклая поверхность ловушки, снизу — плоский контакт.", "claims": ["c3", "c4"], "hypothesis": false},
    {"text": "Если залежь массивная, ожидай, что мощность растёт к центру, а основной объём лежит в своде.", "claims": ["c5", "c6"], "hypothesis": false},
    {"text": "Методика подсчёта и подготовки месторождения должна учитывать эту форму.", "claims": ["c1"], "hypothesis": false},
    {"text": "Проверяй сетку скважин по объёму, а не только по площади. Освещение объёма — это доля залежи, которую охватывают скважины.", "claims": ["c7"], "hypothesis": false}
  ],
  "nuances": [
    {"text": "Не все залежи массивные. Текст говорит только об абсолютном большинстве рифовых залежей.", "claims": ["c2"], "hypothesis": false},
    {"text": "Плоский контакт — упрощение модели массивной залежи. Контакт не обязательно ровный, особенно в других типах залежей.", "claims": ["c4"], "hypothesis": true},
    {"text": "Мощность убывает «закономерно и более менее равномерно». Это общая картина, а не точная формула.", "claims": ["c5"], "hypothesis": false},
    {"text": "Вывод о неравномерном освещении следует из формы залежи. Число скважин и расстояние между ними здесь не заданы.", "claims": ["c7"], "hypothesis": false},
    {"text": "Крылья — края структуры, где мощность падает до нуля.", "claims": ["c5"], "hypothesis": false}
  ],
  "deeper": [
    {"title": "Почему плоский контакт упрощает расчёт", "text": "Если нижняя граница — плоскость, мощность в каждой точке равна расстоянию от поверхности ловушки до этой плоскости. Так мощность можно получить из карты поверхности ловушки.", "claims": [], "hypothesis": true}
  ],
  "procedure": [],
  "numbers_conditions": [
    {"text": "Массивный тип: залежь ограничена сверху выпуклой поверхностью ловушки, а снизу плоскостью ВНК или ГВК.", "claims": ["c3", "c4"]},
    {"text": "Абсолютное большинство залежей нефти и газа, связанных с рифами, — массивного типа.", "claims": ["c2"]},
    {"text": "Мощность убывает от максимальной в центре до нулевой на крыльях.", "claims": ["c5"]}
  ],
  "terms_defined": [
    {"term": "подсчётные параметры", "term_en": "estimation parameters", "abbr": "", "definition": "Величины, по которым подсчитывают запасы залежи. Их изучение — часть методики работ.", "claims": ["c1"]},
    {"term": "сетка скважин", "term_en": "well pattern / well grid", "abbr": "", "definition": "Способ расставить скважины по площади или вдоль профилей. Текст сравнивает сетку, равномерную по площади, и сетку по профилям.", "claims": ["c7"]},
    {"term": "приконтурная зона", "term_en": "near-contour zone", "abbr": "", "definition": "Полоса у края залежи, где она тонкая. Она занимает значительную площадь, но содержит малую часть объёма.", "claims": ["c6"]},
    {"term": "газоводяной контакт (ГВК)", "term_en": "gas-water contact (GWC)", "abbr": "ГВК", "definition": "Граница между газонасыщенной и водонасыщенной частью залежи.", "claims": ["c4"]}
  ],
  "terms_used": ["риф", "залежь", "мощность залежи", "ловушка", "свод ловушки", "массивная залежь", "водонефтяной контакт (ВНК)", "запасы", "разработка", "объём залежи"],
  "formulas": [],
