  "misconception": {
    "pack_id": null,
    "wrong": "Залежь — ровный слой почти одинаковой толщины, поэтому сетка скважин по площади освещает её равномерно.",
    "right": "Массивная залежь тоньше к краям, а основной объём лежит в своде. Сетка, равномерная по площади, освещает объём неравномерно.",
    "claims": ["c5", "c6", "c7"]
  },
  "data_meaning": {
    "inputs": [
      {"text": "Форма поверхности ловушки: выпуклая кровля над залежью.", "claims": ["c3"], "hypothesis": false},
      {"text": "Положение плоского контакта ВНК или ГВК, ниже которого залежи нет.", "claims": ["c4"], "hypothesis": false},
      {"text": "Мощность залежи в разных точках площади, от центра к крыльям.", "claims": ["c5"], "hypothesis": false}
    ],
    "outputs": [
      {"text": "Распределение объёма залежи по площади: основная доля в своде, меньшая — в приконтурной зоне.", "claims": ["c6"], "hypothesis": false},
      {"text": "Оценка того, какие участки плохо освещаются при равномерной сетке скважин.", "claims": ["c7"], "hypothesis": false}
    ],
    "breaks": [
      {"text": "Не все залежи массивные. Вывод относится к абсолютному большинству рифовых залежей.", "claims": ["c2"], "hypothesis": false},
      {"text": "Если контакт не плоский, нижняя граница меняет мощность у краёв.", "claims": [], "hypothesis": true}
    ]
  },
  "it_analogy": {
    "pack_id": null,
    "analogy": "Взвешенная выборка: равномерный шаг по площади даёт одинаковое число точек на единицу площади. Если «вес» точки — объём, то большая часть веса попадает в центр, и равномерный шаг оценивает сумму плохо.",
    "breaks_where": "Веса здесь физические (мощность), а не выбраны аналитиком. Скважина даёт усреднённое знание о пласте, а не точечный замер."
  },
  "now_nuance": {
    "text": "По современной практике (гипотеза): объём залежи обычно оценивают по трёхмерной геологической модели, а не только по карте и сетке скважин. Сетка остаётся важной как источник данных."
  },
  "threshold": {
    "is_threshold": true,
    "why": "После этого узла становится видно: одинаковое число скважин на площадь не даёт одинакового знания об объёме залежи. Без этого нельзя понять, как распределять скважины."
  },
